import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import * as battle from '../lib/battleClient';
import { liveJoinUrl } from '../lib/publicUrl';
import { useBattleRoom } from '../battle/useBattleRoom';
import { useBattleRound } from '../battle/useBattleRound';
import { useRoundAutopilot } from '../battle/useRoundAutopilot';
import { useSyncedPlayback } from '../battle/useSyncedPlayback';
import { useChatVotes } from '../battle/useChatVotes';
import { useUsedGenres } from '../battle/useUsedGenres';
import { secondsUntil, syncClock } from '../battle/clock';
import { useClipSeconds } from '../battle/useClipSeconds';
import { usePickSeconds } from '../battle/usePickSeconds';
import { useAudioSettings } from '../battle/useAudioSettings';
import { BRACKET_CAP, PARTY_ROUNDS, PICK_SECONDS } from '../battle/rules';
import { endBattle, type HostContext, nextHostAction } from '../battle/hostActions';
import { uniqueLeader } from '../battle/voteLeader';
import SongPicker from '../battle/SongPicker';
import LobbySongs from '../battle/LobbySongs';
import EmbedPlayer from '../battle/EmbedPlayer';
import StartPoints from '../battle/StartPoints';
import { embedSourceOf, embedStart } from '../battle/embeds';
import RoomShell, { RoomHeader } from '../battle/RoomShell';
import StreamCard from '../battle/StreamCard';
import PublishChampion from '../battle/PublishChampion';
import { GameSettingsButton, GameSettingsPanel, resolvedVoting, rulesSummary } from '../battle/GameSettings';
import ThemePicker from '../battle/ThemePicker';
import {
  bracketEntrants,
  classicReady,
  hasEntry,
  hostJudges,
  isClassic,
  ownerId,
  songsOf,
  songsPerPlayer,
} from '../battle/playStyle';
import BracketTree from '../battle/ui/BracketTree';
import MatchupCard from '../battle/ui/MatchupCard';
import BoxingMatch from '../battle/ui/BoxingMatch';
import NowPlaying from '../battle/ui/NowPlaying';
import Roster from '../battle/ui/Roster';
import { bracketFighters, pairFighters, spectators } from '../battle/bout';
import { CreateBoxerButton } from '../fight3d/LockerRoom';
import { encodeLoadout, type FighterLoadout } from '../fight3d/loadout';
import {
  Card,
  CountdownRing,
  PromptLabel,
  SectionLabel,
  StatTile,
  TextButton,
  VividButton,
} from '../battle/ui/primitives';
import { CheckIcon, CrownIcon, PlayIcon, TrophyIcon, UsersIcon } from '../battle/ui/icons';
import type {
  BattleMatch,
  BattlePlayer,
  BattleRoom as BattleRoomRow,
  BattleSubmission,
} from '../types/battle';
import '../battle/battle.css';
import '../battle/ui/ui.css';
import '../battle/ui/room.css';

export default function BattleRoom() {
  const { code = '' } = useParams<{ code: string }>();
  const navigate = useNavigate();

  const stored = useMemo(() => {
    battle.takeHandoff(code);
    return battle.loadSession(code);
  }, [code]);
  const [roomId, setRoomId] = useState<string | null>(null);
  const [lookupError, setLookupError] = useState<string | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);
  // Declared up here so Connecting / error returns do not change hook order.
  const startArmedAt = useRef(0);

  useEffect(() => {
    void syncClock();
  }, []);

  useEffect(() => {
    let cancelled = false;
    battle
      .getRoomByCode(code)
      .then((room) => {
        if (cancelled) return;
        if (!room) setLookupError("That room code doesn't exist.");
        else setRoomId(room.id);
      })
      .catch((e) => !cancelled && setLookupError((e as Error).message));
    return () => {
      cancelled = true;
    };
  }, [code]);

  const { room, players, entrants, matches, loading, refresh } = useBattleRoom(
    roomId,
    stored?.token ?? null
  );
  const { round, submissions, votes } = useBattleRound(room);
  const [crowns, setCrowns] = useState<Record<string, number>>({});

  const me = players.find((p) => p.id === stored?.playerId) ?? null;
  const isHost = Boolean(room && me && room.host_player_id === me.id);
  const token = stored?.token ?? null;
  const sentLoadout = useRef<string | null>(null);
  const persistLoadout = useCallback(
    (loadout: FighterLoadout) => {
      if (!token || !me) return;
      const encoded = encodeLoadout(loadout);
      if (encoded === sentLoadout.current || encoded === me.avatar_seed) return;
      sentLoadout.current = encoded;
      void battle.setFighterLoadout(token, encoded, me.id).catch(() => {
        /* board still gets a hashed default if the write misses */
      });
    },
    [token, me]
  );

  const phase = round?.phase ?? null;
  const pick = usePickSeconds();
  const audio = useAudioSettings(submissions);
  const hearAudio = (!room?.host_speaker_enabled || isHost) && audio.where === 'room';
  // A music video plays through a real element on the page, so the hook can
  // only drive it once React has put it there.
  const [videoEl, setVideoEl] = useState<HTMLVideoElement | null>(null);
  const playback = useSyncedPlayback(
    round,
    submissions,
    phase === 'playing' && hearAudio,
    videoEl,
    { volume: audio.volume, gainFor: audio.gainFor, sinkId: audio.sinkId }
  );
  const [embedBlocked, setEmbedBlocked] = useState(false);
  // Track lengths as each YouTube or SoundCloud player reports them, so the
  // host's start slider can reach the end of the song.
  const [durations, setDurations] = useState<Record<string, number>>({});
  const noteDuration = useCallback(
    (id: string, seconds: number) =>
      setDurations((d) => (d[id] === seconds ? d : { ...d, [id]: seconds })),
    []
  );
  const embedPicks = submissions.filter((s) => embedSourceOf(s));
  useSecondTicker(phase === 'picking' || phase === 'judging');

  // Only the host reads chat. Every viewer opening an IRC connection would
  // multiply the load for no gain, and the tally is host-only to write anyway.
  const chatChannel = isHost && room && !room.host_judges ? room.host_twitch_login ?? null : null;
  const chat = useChatVotes({
    enabled: isHost,
    channel: chatChannel,
    round,
    submissions,
    token,
  });

  const usedGenres = useUsedGenres(roomId, round?.id ?? null);

  useEffect(() => {
    if (!loading && roomId && !stored) navigate(`/join/${code.toUpperCase()}`, { replace: true });
  }, [loading, roomId, stored, code, navigate]);

  // Declared above the loading returns so the hook order never shifts.
  const clip = useClipSeconds();

  const { empty: pickedNothing } = useRoundAutopilot({
    token,
    isHost,
    round,
    submissions,
    playbackFinished: playback.finished,
    clipSeconds: clip.seconds,
    clipStart: clip.start,
  });

  const guard = useCallback(async (fn: () => Promise<unknown>) => {
    setActionError(null);
    setBusy(true);
    try {
      await fn();
    } catch (e) {
      setActionError((e as Error).message);
    } finally {
      setBusy(false);
    }
  }, []);

  useEffect(() => {
    if (!roomId || room?.format === 'bracket') return;
    let live = true;
    void Promise.all([battle.getRounds(roomId), battle.getRoomSubmissions(roomId)]).then(
      ([rounds, subs]) => {
        const byId = new Map(subs.map((s) => [s.id, s]));
        const next: Record<string, number> = {};
        for (const r of rounds) {
          const sub = r.winner_submission_id ? byId.get(r.winner_submission_id) : undefined;
          if (!sub) continue;
          next[sub.player_id] = (next[sub.player_id] ?? 0) + 1;
        }
        if (live) setCrowns(next);
      }
    );
    return () => {
      live = false;
    };
  }, [roomId, room?.format, round?.phase, round?.winner_submission_id]);

  if (lookupError) {
    return (
      <RoomShell>
        <Card>
          <h1 className="bt-h1">Can't open this room</h1>
          <p className="bt-sub">{lookupError}</p>
          <VividButton onClick={() => navigate('/battle')}>Back</VividButton>
        </Card>
      </RoomShell>
    );
  }

  if (loading || !room) {
    return (
      <RoomShell>
        <Card>
          <p className="bt-sub" style={{ margin: 0 }}>
            Loading room…
          </p>
        </Card>
      </RoomShell>
    );
  }

  const connected = players.filter((p) => p.is_connected);
  const joinUrl = liveJoinUrl(room.code);
  // Entrants, so a bracket slot holding someone's second song still reads as
  // their name.
  const nameOf = (id: string | null) =>
    entrants.find((p) => p.id === id)?.display_name ?? 'Someone';
  const ownerOf = (id: string | null | undefined) => {
    const row = id ? entrants.find((p) => p.id === id) : undefined;
    return row ? ownerId(row) : id ?? null;
  };
  const judging = hostJudges(room);
  const mySongs = me ? songsOf(entrants, me.id) : [];
  const songCount = bracketEntrants(room, entrants).filter(hasEntry).length;

  const isBracket = room.format === 'bracket';
  const classic = isClassic(room);
  const currentMatch = matches.find((m) => m.id === room.current_match_id) ?? null;

  // The bracket is decided when the match that feeds nowhere has a winner.
  const bracketChampionId =
    matches.find((m) => m.next_match_id === null && m.winner_player_id)?.winner_player_id ?? null;
  const partyChampionId =
    !isBracket && room.status === 'complete' ? crownLeader(crowns, players) : null;
  const championId = isBracket ? bracketChampionId : partyChampionId;

  // In a bracket only the two competitors pick a song; everybody else is an
  // audience with a vote. A player whose second song is in the matchup is a
  // competitor too.
  const isCompetitor = (p: BattlePlayer | null) =>
    Boolean(
      p &&
        currentMatch &&
        (ownerOf(currentMatch.player_a_id) === p.id || ownerOf(currentMatch.player_b_id) === p.id)
    );

  const judgeId = round?.judge_player_id ?? null;
  const isJudge = Boolean(me && judgeId === me.id);
  const votingMode = resolvedVoting(room);
  const canPick = isBracket
    ? isCompetitor(me)
    : votingMode === 'judge'
      ? Boolean(me && me.id !== judgeId)
      : Boolean(me);

  const myVote = votes.find((v) => v.voter_player_id === me?.id) ?? null;
  const mySubmission = submissions.find((s) => s.player_id === me?.id) ?? null;
  const isMine = (s: BattleSubmission) => Boolean(me && ownerOf(s.player_id) === me.id);

  // A room tied to a Twitch channel hands the decision to chat, so the in-room
  // crown buttons become a read-only scoreboard for everyone. The host shows
  // its own live counts because those update between reports; everyone else
  // reads what the host last published.
  // A judging host overrules chat: they asked to make the call themselves.
  const chatTally =
    room.host_twitch_login && !judging
      ? isHost
        ? chat.counts
        : round?.chat_tally ?? {}
      : null;

  // Nobody in the room is eligible to vote when every player is in the
  // matchup, which is exactly what a two player bracket looks like. The AI
  // judge exists for that case rather than leaving the round wedged.
  const needsAiJudge =
    isBracket && !chatTally && connected.length > 0 && connected.every((p) => isCompetitor(p));

  const canVote =
    Boolean(me) &&
    !needsAiJudge &&
    !chatTally &&
    (votingMode === 'everyone'
      ? !(isBracket && isCompetitor(me))
      : votingMode === 'host'
        ? isHost
        : isJudge);

  const submissionOf = (playerId: string | null) =>
    playerId ? submissions.find((s) => s.player_id === playerId) ?? null : null;

  const matchupSides = currentMatch
    ? {
        left: {
          name: nameOf(currentMatch.player_a_id),
          votes: voteCountFor(currentMatch.player_a_id),
        },
        right: {
          name: nameOf(currentMatch.player_b_id),
          votes: voteCountFor(currentMatch.player_b_id),
        },
      }
    : null;

  function voteCountFor(playerId: string | null): number | null {
    // One judge, one verdict: "0 votes / 1 vote" under the fighters is noise.
    if (judging) return null;
    if (phase !== 'judging' && phase !== 'revealed') return null;
    const submission = submissionOf(playerId);
    if (!submission) return null;
    if (chatTally) return chatTally[submission.id] ?? 0;
    return votes.filter((v) => v.submission_id === submission.id).length;
  }

  const ballotCounts: Record<string, number> = {};
  for (const s of submissions) {
    ballotCounts[s.id] = chatTally
      ? chatTally[s.id] ?? 0
      : votes.filter((v) => v.submission_id === s.id).length;
  }
  const voteLeader = uniqueLeader(ballotCounts);
  const ballotTotal = Object.values(ballotCounts).reduce((a, b) => a + b, 0);
  const fight = isBracket
    ? bracketFighters(currentMatch, submissions, ballotCounts, players, nameOf)
    : pairFighters(submissions, ballotCounts, players, nameOf);

  /**
   * Which fighter to crown.
   *
   * The round decides a winner before the match record knows about it, since
   * reporting the match is the host's next action. Reading the round first
   * means the crown lands with the reveal rather than a click later.
   */
  const winnerSide = (): 'left' | 'right' | null => {
    const roundWinner = submissions.find((s) => s.id === round?.winner_submission_id)?.player_id;
    const winnerId = roundWinner ?? currentMatch?.winner_player_id;
    if (!winnerId || !currentMatch) return null;
    return winnerId === currentMatch.player_a_id ? 'left' : 'right';
  };

  const stageLabel = isBracket
    ? currentMatch
      ? roundTitle(currentMatch.bracket_round, matches)
      : `${connected.length} in the room`
    : round
      ? `Round ${round.round_number} of ${PARTY_ROUNDS}`
      : `${connected.length} in the room`;

  const saveSettings = (patch: Parameters<typeof battle.updateRoomSettings>[1]) =>
    void guard(async () => {
      if (patch.theme !== undefined) startArmedAt.current = Date.now() + 1200;
      await battle.updateRoomSettings(token!, patch);
      await refresh();
    });

  // The board at /tv runs these too, so a host on a stream can drive the game
  // from whichever screen they are already looking at.
  const hostCtx: HostContext | null = token
    ? {
        token,
        room,
        matches,
        round,
        submissions,
        voteLeader,
        usedGenres,
        clipSeconds: clip.seconds,
        clipStart: clip.start,
        pickSeconds: pick.seconds,
        refresh,
      }
    : null;

  const action =
    isHost && hostCtx
      ? nextHostAction(hostCtx, {
          ready: classic
            ? classicReady(room, entrants)
            : connected.filter((p) => !judging || p.id !== room.host_player_id).length >= room.min_players,
          needsAiJudge,
          empty: pickedNothing,
          finished: championId !== null,
        })
      : null;

  const startHint = isHost && !round ? startBlocker(room, songCount, connected) : null;

  const runAction = () => {
    if (!action) return;
    if (action.id === 'start' && Date.now() < startArmedAt.current) return;
    // The host's click is a user gesture. Spend it unlocking audio so the
    // first song is not blocked by the browser after the clock starts.
    if (action.id === 'start' || action.id === 'play') playback.prime();
    void guard(action.run);
  };

  const settingsAudio = {
    volume: audio.volume,
    onVolume: audio.setVolume,
    autoLevel: audio.autoLevel,
    onAutoLevel: audio.setAutoLevel,
    where: audio.where,
    onWhere: audio.setWhere,
  };

  const settingsPanel = (
    <GameSettingsPanel
      room={room}
      playerCount={players.length}
      aiJudge={needsAiJudge}
      clipSeconds={clip.seconds}
      clipStart={clip.start}
      onClipSeconds={clip.setSeconds}
      onClipStart={clip.setStart}
      pickSeconds={pick.seconds}
      onPickSeconds={pick.setSeconds}
      audio={settingsAudio}
      onEndBattle={
        hostCtx && room.status !== 'lobby' && room.status !== 'complete'
          ? () => void guard(() => endBattle(hostCtx))
          : undefined
      }
      onChange={saveSettings}
    />
  );

  return (
    <RoomShell>
      <RoomHeader
        code={room.code}
        stage={
          round
            ? `${stageLabel} · ${round.genre}`
            : classic && room.theme
              ? room.theme
              : stageLabel
        }
        compact={Boolean(round) || championId !== null}
      />

      {/* ---------- Champion ---------- */}
      {championId && (
        <Card tone="orange" className="bt-champion">
          <span className="bt-champion__trophy">
            <TrophyIcon size={40} />
          </span>
          <SectionLabel tone="orange">Champion</SectionLabel>
          <h2 className="bt-champion__name">{nameOf(championId)}</h2>
          <p className="bt-sub">
            {isBracket ? 'Winner of the whole bracket.' : `Most crowns after ${PARTY_ROUNDS} rounds.`}
          </p>

          {action?.id === 'rematch' && (
            <VividButton disabled={busy} onClick={runAction}>
              {action.label}
            </VividButton>
          )}

          {/* Bracket only: the RPC refuses a party room, which has no final
              match to read a winning song off. */}
          {isHost && isBracket && token && <PublishChampion token={token} />}
        </Card>
      )}

      {/* ---------- Lobby ---------- */}
      {!round && !championId && (
        <>
          <Card className="bt-lobby">
            <p className="bt-lobby__pitch">
              {classic
                ? 'One vibe for the whole game. Share the code, lock songs in, then start when everyone is here.'
                : isBracket
                  ? 'Two songs go head to head. The room votes until one is left.'
                  : votingMode === 'host'
                    ? 'Everyone picks. You crown the winner. Best of three.'
                    : votingMode === 'everyone'
                      ? 'Everyone picks. The room votes. Best of three.'
                      : 'Everyone picks. A judge crowns the winner. Best of three.'}
            </p>

            {classic && (
              <div className="bt-genre">
                <PromptLabel>This game&rsquo;s vibe</PromptLabel>
                {room.theme ? (
                  <h2 className="bt-genre__title">{room.theme}</h2>
                ) : (
                  <p className="bt-sub bt-lobby__hint">
                    {isHost
                      ? 'Pick the vibe. It stays the same the whole game.'
                      : `Waiting for ${nameOf(room.host_player_id)} to pick a vibe.`}
                  </p>
                )}
                {isHost && (
                  <ThemePicker
                    value={room.theme ?? ''}
                    onChange={(theme) => saveSettings({ theme })}
                  />
                )}
              </div>
            )}

            {classic && token && me && room.theme && isHost && judging && (
              <p className="bt-sub bt-sub--center bt-lobby__hint">
                You are judging. You stay out of the bracket and pick the winner of every match.
              </p>
            )}

            {classic && token && me && room.theme && !(isHost && judging) && (
              <LobbySongs
                songs={mySongs}
                limit={songsPerPlayer(room)}
                busy={busy}
                // Not through `guard`: a refused song (already picked, limit
                // reached) has to surface under the search box it came from,
                // which SongPicker does when this rejects.
                onAdd={async (song) => {
                  await battle.addLobbySong(token, song);
                  await refresh();
                }}
                onRemove={(entryId) =>
                  void guard(async () => {
                    await battle.removeEntry(token, entryId);
                    await refresh();
                  })
                }
              />
            )}

            {token && me && (
              <CreateBoxerButton name={me.display_name} seed={me.avatar_seed} onChange={persistLoadout} />
            )}
          </Card>

          <Card>
            <SectionLabel>
              {classic
                ? `Songs in · ${songCount}/${songsPerPlayer(room) > 1 ? BRACKET_CAP : room.max_players}`
                : `Players · ${connected.length}/${room.max_players}`}
            </SectionLabel>
            <div style={{ marginTop: 12 }}>
              <Roster
                players={players}
                hostId={room.host_player_id}
                judgeId={judging ? room.host_player_id : null}
                meId={me?.id ?? null}
                waitingSlots={classic ? 0 : Math.max(0, room.min_players - connected.length)}
                statusOf={
                  classic
                    ? (p) =>
                        judging && p.id === room.host_player_id
                          ? null
                          : songsOf(entrants, p.id).length > 0
                            ? 'locked'
                            : 'unpicked'
                    : undefined
                }
                songCountOf={
                  classic && songsPerPlayer(room) > 1
                    ? (p) => songsOf(entrants, p.id).length
                    : undefined
                }
              />
            </div>

            {classic && songCount > 0 && (
              <p className="bt-sub" style={{ margin: '12px 0 0' }}>
                {songCount === 1
                  ? 'One song is locked in. Titles stay hidden until you start.'
                  : `${songCount} songs are locked in. Titles stay hidden until you start.`}
              </p>
            )}

            {isHost ? (
              // The start button is always on screen for the host, greyed
              // out until the room is ready, with the reason written above
              // it. It used to appear only once enough songs were in, so a
              // host who had just typed the vibe saw a roster of "Picking"
              // and no way to start, and read that as the game being stuck.
              <>
                {startHint && (
                  <p
                    className="bt-sub bt-sub--center"
                    style={{ marginBottom: action?.id === 'start' ? 12 : 0 }}
                  >
                    {startHint}
                  </p>
                )}
                {action?.id === 'start' && (
                  <VividButton
                    icon={<PlayIcon size={18} />}
                    disabled={busy || action.disabled}
                    onClick={runAction}
                  >
                    {action.label}
                  </VividButton>
                )}
              </>
            ) : (
              <p className="bt-sub bt-sub--center" style={{ marginBottom: 0 }}>
                Waiting for {nameOf(room.host_player_id)} to start.
              </p>
            )}
          </Card>

          {isHost && isBracket && <StreamCard code={room.code} channel={room.host_twitch_login} />}

          {isHost && (
            <>
              {settingsOpen && settingsPanel}
              <GameSettingsButton
                summary={rulesSummary(room, needsAiJudge, clip.seconds, pick.seconds)}
                open={settingsOpen}
                onClick={() => setSettingsOpen((o) => !o)}
              />
            </>
          )}
        </>
      )}

      {/* ---------- Live fight ---------- */}
      {fight && phase && phase !== 'picking' && !championId && round && (
        <BoxingMatch
          a={fight.a}
          b={fight.b}
          phase={phase}
          winner={
            submissions.find((s) => s.id === round.winner_submission_id)?.player_id
              ? ((): 'a' | 'b' | null => {
                  const id =
                    submissions.find((s) => s.id === round.winner_submission_id)?.player_id ??
                    currentMatch?.winner_player_id ??
                    null;
                  if (!id) return null;
                  if (currentMatch) {
                    if (id === currentMatch.player_a_id) return 'a';
                    if (id === currentMatch.player_b_id) return 'b';
                  }
                  if (submissions[0]?.player_id === id) return 'a';
                  if (submissions[1]?.player_id === id) return 'b';
                  return null;
                })()
              : null
          }
          nowPlaying={
            phase === 'playing' ? ((): 'a' | 'b' | null => {
              const id = playback.current?.player_id;
              if (!id) return null;
              if (currentMatch) {
                if (id === currentMatch.player_a_id) return 'a';
                if (id === currentMatch.player_b_id) return 'b';
              }
              if (submissions[0]?.player_id === id) return 'a';
              if (submissions[1]?.player_id === id) return 'b';
              return null;
            })() : null
          }
          walkSeconds={playback.perSong}
          walkOffset={playback.offset}
          fightKey={round.id}
          chatChannel={room.host_twitch_login}
          roundLabel={stageLabel}
          fans={spectators(players, fight.a.name, fight.b.name)}
          judgeName={judging ? nameOf(room.host_player_id) : null}
          onPick={
            judging && isHost && phase === 'judging'
              ? (side) => {
                  const pick = side === 'a' ? fight.a : fight.b;
                  const sub =
                    submissions.find(
                      (s) => s.song_title === pick.songTitle && nameOf(s.player_id) === pick.name
                    ) ?? submissions[side === 'a' ? 0 : 1];
                  if (!sub) return;
                  void guard(async () => {
                    await battle.castVote(token!, round.id, sub.id);
                    await battle.setRoundWinner(token!, round.id, sub.id);
                  });
                }
              : undefined
          }
        />
      )}

      {/* ---------- Matchup, shown through every phase of a match ---------- */}
      {isBracket && !championId && currentMatch && matchupSides && phase && !fight && (
        <MatchupCard
          title={roundTitle(currentMatch.bracket_round, matches)}
          left={matchupSides.left}
          right={matchupSides.right}
          winnerSide={phase === 'revealed' ? winnerSide() : null}
        />
      )}

      {/* ---------- Picking ---------- */}
      {phase === 'picking' && !championId && round && (
        <Card>
          <div className="bt-genre">
            <PromptLabel>{classic ? 'This game\u2019s vibe' : 'This round\u2019s vibe'}</PromptLabel>
            <h2 className="bt-genre__title">{round.genre}</h2>
          </div>

          <div className="bt-tiles">
            <StatTile
              icon={<UsersIcon size={17} />}
              value={`${submissions.length}/${expectedPickers(currentMatch, connected, votingMode === 'judge' ? judgeId : null)}`}
              label="Locked in"
            />
            {round.phase_deadline_at ? (
              <CountdownRing
                seconds={secondsUntil(round.phase_deadline_at)}
                progress={ringProgress(round.phase_deadline_at, pickWindowSeconds(round, pick.seconds))}
              />
            ) : (
              <StatTile
                icon={<PlayIcon size={17} />}
                value="No clock"
                label="Take your time"
              />
            )}
            <StatTile
              icon={<TrophyIcon size={17} />}
              value={
                isBracket
                  ? roundTitle(currentMatch?.bracket_round ?? 1, matches).split(' ')[0]
                  : `${round.round_number}/${PARTY_ROUNDS}`
              }
              label={isBracket ? 'Stage' : 'Round'}
            />
          </div>

          {canPick ? (
            mySubmission ? (
              <Card tone="green" className="bt-locked">
                <span className="bt-locked__icon">
                  <CheckIcon size={22} />
                </span>
                <SectionLabel>Your pick is in</SectionLabel>
                <strong className="bt-locked__title">{mySubmission.song_title}</strong>
                <span className="bt-sub">{mySubmission.song_artist}</span>
              </Card>
            ) : (
              <SongPicker
                disabled={busy}
                onPick={(song) =>
                  guard(() =>
                    battle.submitSong(token!, round.id, {
                      title: song.title,
                      artist: song.artist,
                      artworkUrl: song.artworkUrl,
                      previewUrl: song.previewUrl,
                      externalId: song.externalId,
                      source: song.source,
                    })
                  )
                }
              />
            )
          ) : (
            <p className="bt-sub bt-sub--center" style={{ margin: 0 }}>
              {isJudge && votingMode === 'judge'
                ? "You're the judge this round. Sit back while everyone picks, then you crown the winner."
                : matchupSides
                  ? `${matchupSides.left.name} and ${matchupSides.right.name} are picking. Get ready to vote.`
                  : 'Waiting for the next round.'}
            </p>
          )}

          {action?.id === 'play' && (
            <VividButton
              // Once everyone is in, this is the only thing left to do, so it
              // stops being a shortcut and becomes the call to action.
              variant={
                submissions.length >= expectedPickers(currentMatch, connected, votingMode === 'judge' ? judgeId : null)
                  ? 'filled'
                  : 'outline'
              }
              tone="blue"
              icon={<PlayIcon size={16} />}
              disabled={busy}
              onClick={runAction}
            >
              {action.label}
            </VividButton>
          )}

          {/* The clock ran out with an empty round. There is nothing to play
              and nobody to crown, so the only way forward is more time. */}
          {pickedNothing && (
            <>
              <p className="bt-sub bt-sub--center" style={{ marginBottom: isHost ? 12 : 0 }}>
                Time&rsquo;s up and nobody picked a song.
              </p>
              {action?.id === 'extend' && (
                <VividButton tone="blue" disabled={busy} onClick={runAction}>
                  {action.label}
                </VividButton>
              )}
            </>
          )}
        </Card>
      )}

      {/* ---------- Playing ---------- */}
      {phase === 'playing' && !championId && (
        <Card>
          <div className="bt-phase-head">
            <SectionLabel tone="blue">
              Track {Math.min(playback.index + 1, playback.total)} of {playback.total}
            </SectionLabel>
          </div>

          {(playback.blocked || embedBlocked) && hearAudio && (
            <VividButton
              tone="blue"
              icon={<PlayIcon size={18} />}
              onClick={() => {
                playback.unblock();
                setEmbedBlocked(false);
              }}
            >
              Tap to hear the battle
            </VividButton>
          )}

          {!hearAudio && (
            <p className="bt-sub bt-sub--center">Songs are playing from the host&rsquo;s speaker.</p>
          )}

          {playback.current ? (
            <>
              <NowPlaying
                title={playback.current.song_title}
                artist={playback.current.song_artist}
                pickedBy={nameOf(playback.current.player_id)}
                artworkUrl={playback.current.artwork_url}
                progress={playback.offset / playback.perSong}
              />

              {isHost && hearAudio && submissions.length > 0 && (
                <ul className="bt-mix">
                  {submissions.map((s) => {
                    const trim = audio.trimOf(s.id);
                    const live = playback.current?.id === s.id;
                    return (
                      <li key={s.id} className={`bt-mix__row${live ? ' bt-mix__row--live' : ''}`}>
                        <span className="bt-mix__name">{s.song_title}</span>
                        <input
                          className="bt-slider"
                          type="range"
                          min={0}
                          max={200}
                          step={5}
                          value={Math.round(trim * 100)}
                          aria-label={`Volume for ${s.song_title}`}
                          onChange={(e) => audio.setTrim(s.id, Number(e.currentTarget.value) / 100)}
                        />
                        <span className="bt-mix__pct">{Math.round(trim * 100)}%</span>
                      </li>
                    );
                  })}
                </ul>
              )}

              {/* A music video pick is the same clip on the same clock, just
                  with something to look at. The hook drives this element
                  directly, so it has to be on the page before it can play. */}
              {hearAudio && playback.needsScreen && (
                <video
                  ref={setVideoEl}
                  className="bt-video"
                  playsInline
                  controls={false}
                  poster={playback.current.artwork_url ?? undefined}
                />
              )}

              {/* SoundCloud and YouTube picks play in the provider's own
                  player, which has to stay on screen. iTunes previews are
                  plain audio and need nothing here. */}
              {hearAudio && embedSourceOf(playback.current) && (
                <EmbedPlayer
                  source={embedSourceOf(playback.current)!}
                  externalId={playback.current.external_id ?? ''}
                  offset={embedStart(playback.current) + playback.offset}
                  playing
                  volume={audio.volume * audio.gainFor(playback.current)}
                  onBlocked={setEmbedBlocked}
                  onDuration={(d) => noteDuration(playback.current!.id, d)}
                />
              )}
            </>
          ) : (
            <p className="bt-sub bt-sub--center" style={{ margin: 0 }}>
              Getting the first track ready…
            </p>
          )}

          {isHost && token && embedPicks.length > 0 && (
            <StartPoints
              token={token}
              picks={embedPicks}
              liveId={playback.current?.id ?? null}
              durations={durations}
            />
          )}

          {/* One shared countdown, read off the same server clock everywhere, so
              a room full of embeds changes track together even though each
              player takes a different amount of time to load. */}
          {playback.secondsUntilNext !== null && playback.secondsUntilNext <= 3 && (
            <p className="bt-countdown" aria-live="polite">
              Next up in {Math.ceil(playback.secondsUntilNext)}
            </p>
          )}
        </Card>
      )}

      {/* ---------- Judging ---------- */}
      {phase === 'judging' && !championId && round && (
        <Card>
          <div className="bt-phase-head">
            <SectionLabel tone="orange">Crown a winner</SectionLabel>
            <p className="bt-sub bt-sub--center">
              {chatTally ? (
                voteLeader ? (
                  <>
                    Twitch chat decides. Viewers type <strong>1</strong> or <strong>2</strong>.
                  </>
                ) : ballotTotal === 0 ? (
                  'No chat votes yet. Revealing lets the AI judge call it.'
                ) : (
                  'Chat is tied. Revealing lets the AI judge call it.'
                )
              ) : judging ? (
                isHost
                  ? 'Tap the song that wins. It is crowned straight away.'
                  : `${nameOf(room.host_player_id)} is judging this one.`
              ) : needsAiJudge ? (
                'Nobody in the room can vote on their own song, so the AI judge calls it.'
              ) : votingMode === 'host' ? (
                isHost ? 'You pick the winner.' : `Waiting for ${nameOf(room.host_player_id)} to crown a winner.`
              ) : votingMode === 'judge' ? (
                isJudge
                  ? 'You are the judge. Pick the song you liked more.'
                  : `Waiting for ${nameOf(judgeId)} to crown a winner.`
              ) : isBracket && isCompetitor(me) ? (
                'You are in this matchup, so you sit this vote out.'
              ) : voteLeader ? (
                isBracket
                  ? 'Everyone votes, except the two in the matchup.'
                  : 'Everyone in the room votes. You cannot pick your own song.'
              ) : ballotTotal === 0 ? (
                'No votes yet. Revealing lets the AI judge call it.'
              ) : (
                "It's a tie. Revealing lets the AI judge call it."
              )}
            </p>
          </div>

          <ul className="bt-ballot">
            {submissions.map((s, i) => {
              const mine = isMine(s);
              const chosen = myVote?.submission_id === s.id;
              const count = chatTally
                ? chatTally[s.id] ?? 0
                : votes.filter((v) => v.submission_id === s.id).length;

              // A judging host is not casting one of many votes, so there
              // are no numbers to type and no tallies: the tap is the verdict.
              if (judging) {
                return (
                  <li key={s.id}>
                    <button
                      className="bt-choice bt-choice--judge"
                      disabled={busy || !isHost}
                      onClick={() =>
                        void guard(async () => {
                          await battle.castVote(token!, round.id, s.id);
                          await battle.setRoundWinner(token!, round.id, s.id);
                        })
                      }
                    >
                      {s.artwork_url ? (
                        <img src={s.artwork_url} alt="" className="bt-choice__art" />
                      ) : (
                        <div className="bt-choice__art bt-choice__art--empty" />
                      )}
                      <span className="bt-choice__text">
                        <strong>{s.song_title}</strong>
                        <span>
                          {s.song_artist} · {nameOf(s.player_id)}
                        </span>
                      </span>
                      {isHost && (
                        <span className="bt-choice__crown">
                          <CrownIcon size={16} />
                          Crown
                        </span>
                      )}
                    </button>
                  </li>
                );
              }

              return (
                <li key={s.id}>
                  <button
                    className={`bt-choice${chosen ? ' bt-choice--chosen' : ''}`}
                    disabled={busy || mine || Boolean(myVote) || !canVote}
                    onClick={() => void guard(() => battle.castVote(token!, round.id, s.id))}
                  >
                    <span className="bt-choice__num">{i + 1}</span>

                    {s.artwork_url ? (
                      <img src={s.artwork_url} alt="" className="bt-choice__art" />
                    ) : (
                      <div className="bt-choice__art bt-choice__art--empty" />
                    )}

                    <span className="bt-choice__text">
                      <strong>{s.song_title}</strong>
                      <span>
                        {s.song_artist} · {nameOf(s.player_id)}
                      </span>
                    </span>

                    <span className="bt-choice__count">{count}</span>
                  </button>
                </li>
              );
            })}
          </ul>

          {chatChannel && (
            <p className="bt-sub bt-sub--center" style={{ marginBottom: 0 }}>
              {chat.connected
                ? `Chat is voting in #${chatChannel}. ${chat.total} ${
                    chat.total === 1 ? 'vote' : 'votes'
                  } so far.`
                : `Connecting to #${chatChannel}…`}
            </p>
          )}

          {action?.id === 'reveal' && !judging && (
            <VividButton
              icon={<CrownIcon size={18} />}
              disabled={busy || action.disabled}
              onClick={runAction}
            >
              {action.label}
            </VividButton>
          )}
        </Card>
      )}

      {/* ---------- Revealed ---------- */}
      {phase === 'revealed' && !championId && round && (
        <Card tone="orange" className="bt-reveal">
          {(() => {
            const winning = submissions.find((s) => s.id === round.winner_submission_id);
            if (!winning) {
              return (
                <p className="bt-sub" style={{ margin: 0 }}>
                  No winner recorded for this round.
                </p>
              );
            }
            return (
              <>
                <span className="bt-reveal__crown">
                  <CrownIcon size={34} />
                </span>
                <SectionLabel tone="orange">Takes the round</SectionLabel>
                <h2 className="bt-reveal__name">{nameOf(winning.player_id)}</h2>
                <p className="bt-reveal__song">
                  {winning.song_title} · {winning.song_artist}
                </p>
              </>
            );
          })()}

          {action?.id === 'next' && (
            <VividButton disabled={busy} onClick={runAction}>
              {action.label}
            </VividButton>
          )}
        </Card>
      )}

      {isBracket && matches.length > 0 && (
        <BracketTree
          matches={matches}
          players={entrants}
          currentMatchId={room.current_match_id}
        />
      )}

      {round && isHost && isBracket && <StreamCard code={room.code} channel={room.host_twitch_login} />}

      {round && isHost && (
        <>
          {settingsOpen && settingsPanel}
          <GameSettingsButton
            summary={rulesSummary(room, needsAiJudge, clip.seconds, pick.seconds)}
            open={settingsOpen}
            onClick={() => setSettingsOpen((o) => !o)}
          />
        </>
      )}

      <Card>
        {/* The lobby already gives the roster a card of its own, with empty
            seats and a count. Repeating it here would just be the same list
            twice on the same screen. */}
        {round ? (
          <>
            {token && me && !championId && (
              <div className="create-boxer-slot">
                <CreateBoxerButton name={me.display_name} seed={me.avatar_seed} onChange={persistLoadout} />
              </div>
            )}
            <SectionLabel>In the room</SectionLabel>
            <div style={{ marginTop: 12 }}>
              <Roster
                players={players}
                hostId={room.host_player_id}
                judgeId={judgeId}
                meId={me?.id ?? null}
                statusOf={
                  phase === 'picking'
                    ? (p) =>
                        isBracket
                          ? !isCompetitor(p)
                            ? null
                            : submissions.some((s) => s.player_id === p.id)
                              ? 'locked'
                              : 'picking'
                          : p.id === judgeId && votingMode === 'judge'
                            ? null
                            : submissions.some((s) => s.player_id === p.id)
                              ? 'locked'
                              : 'picking'
                    : undefined
                }
              />
            </div>
          </>
        ) : (
          <p className="bt-joinurl" style={{ marginTop: 0 }}>
            Join at <strong>{joinUrl}</strong>
          </p>
        )}

        <TextButton
          onClick={() =>
            void guard(async () => {
              if (token) await battle.leaveRoom(token).catch(() => {});
              battle.clearSession(code);
              navigate('/battle');
            })
          }
        >
          Leave room
        </TextButton>
      </Card>

      {actionError && <div className="bt-error">{actionError}</div>}
    </RoomShell>
  );
}

// ---------------------------------------------------------------

/** How many people are expected to submit this round. */
function expectedPickers(
  match: BattleMatch | null,
  connected: BattlePlayer[],
  judgeId: string | null
): number {
  if (match) return [match.player_a_id, match.player_b_id].filter(Boolean).length;
  return connected.filter((p) => p.id !== judgeId).length;
}

/**
 * Why the host cannot start yet, in one line, or null once they can.
 *
 * Classic waits on songs rather than seats: a viewer who never picks is an
 * audience, not a missing player. TuneBoxed waits on people in the room.
 */
function startBlocker(
  room: BattleRoomRow,
  songCount: number,
  connected: BattlePlayer[]
): string | null {
  if (isClassic(room)) {
    if (!room.theme?.trim()) return 'Pick a vibe so people know what to submit.';
    const missing = room.min_players - songCount;
    if (missing > 0) {
      return `Waiting for ${missing} more ${missing === 1 ? 'song' : 'songs'}. Everyone locks a song in, then you start the ${
        room.format === 'bracket' ? 'bracket' : 'battle'
      }.`;
    }
    return null;
  }
  const players = hostJudges(room)
    ? connected.filter((p) => p.id !== room.host_player_id)
    : connected;
  const missing = room.min_players - players.length;
  return missing > 0 ? `Waiting for ${missing} more to start.` : null;
}

function crownLeader(crowns: Record<string, number>, players: BattlePlayer[]): string | null {
  let best: string | null = null;
  let n = 0;
  for (const p of players) {
    const c = crowns[p.id] ?? 0;
    if (c > n) {
      n = c;
      best = p.id;
    }
  }
  return n > 0 ? best : null;
}

/**
 * Bracket rounds are named backwards from the end, which is how people
 * actually talk about them.
 */
function roundTitle(round: number, matches: BattleMatch[]): string {
  const finalRound = matches.length ? Math.max(...matches.map((m) => m.bracket_round)) : round;
  const fromEnd = finalRound - round;
  if (fromEnd === 0) return 'Final';
  if (fromEnd === 1) return 'Semifinal';
  if (fromEnd === 2) return 'Quarterfinal';
  return `Round ${round}`;
}

/** How much of the pick window is left, as 1 down to 0, for the ring. */
function ringProgress(deadline: string | null, total: number): number {
  if (!deadline || total <= 0) return 0;
  return Math.max(0, Math.min(1, secondsUntil(deadline) / total));
}

/**
 * How long this pick window actually is.
 *
 * Prefer the gap between the round opening and its deadline, so a host who
 * dragged the slider after this round started does not shrink the ring of a
 * clock that is already running. Fall back to the host's preference, then
 * the default, for a round that has no deadline.
 */
function pickWindowSeconds(
  round: { created_at: string; phase_deadline_at: string | null },
  preferred: number
): number {
  if (round.phase_deadline_at) {
    const span =
      (new Date(round.phase_deadline_at).getTime() - new Date(round.created_at).getTime()) / 1000;
    if (Number.isFinite(span) && span > 0) return span;
  }
  return preferred > 0 ? preferred : PICK_SECONDS;
}

/**
 * Re-renders once a second so a deadline visibly counts down.
 *
 * The playing phase gets this for free because the playback hook ticks four
 * times a second, but picking and judging derive their clock purely from a
 * timestamp and would otherwise sit frozen until the next realtime event.
 */
function useSecondTicker(active: boolean): number {
  const [count, setCount] = useState(0);
  useEffect(() => {
    if (!active) return;
    const t = setInterval(() => setCount((n) => n + 1), 1000);
    return () => clearInterval(t);
  }, [active]);
  return count;
}

